package in.kashtbhanjan.shop;

import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
  final int ORANGE=Color.rgb(239,108,0), DEEP=Color.rgb(191,54,12), CREAM=Color.rgb(255,248,225), INK=Color.rgb(62,39,35);
  DB db; LinearLayout root,body,nav; String page="home"; EditText nameBox,phoneBox,priceBox,qtyBox,amountBox,searchBox; long selectedCustomer=-1,selectedProduct=-1; ArrayList<Long> customerIds=new ArrayList<>(), productIds=new ArrayList<>();
  public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);showHome();}
  TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(12,9,12,9);return t;}
  GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
  Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackground(bg(ORANGE,18));b.setOnClickListener(v->r.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);b.setLayoutParams(p);return b;}
  EditText edit(String hint, boolean numeric){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextSize(16);e.setPadding(14,10,14,10);e.setBackground(bg(Color.WHITE,12));if(numeric)e.setInputType(8194);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,5);e.setLayoutParams(p);return e;}
  void base(String subtitle){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(CREAM);setContentView(root);LinearLayout header=new LinearLayout(this);header.setOrientation(1);header.setPadding(14,8,14,10);header.setBackgroundColor(DEEP);TextView title=text("॥ श्री कष्टभंजन देव ॥",20,Color.WHITE);title.setGravity(17);header.addView(title);TextView shop=text("श्री कष्टभंजन देव पशु आहार करजी",18,Color.WHITE);shop.setGravity(17);shop.setTypeface(null,1);header.addView(shop);TextView sub=text(subtitle,13,Color.WHITE);sub.setGravity(17);header.addView(sub);root.addView(header);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(14,10,14,18);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setPadding(5,5,5,5);nav.setBackgroundColor(Color.rgb(255,224,178));String[][] items={{"होम","home"},{"ग्राहक","customers"},{"सामान","products"},{"हिसाब","reports"},{"बैकअप","backup"}};for(String[] it:items){TextView n=text(it[0],13,DEEP);n.setGravity(17);n.setOnClickListener(v->go(it[1]));nav.addView(n,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);}
  void go(String p){page=p;switch(p){case"home":showHome();break;case"customers":showCustomers();break;case"products":showProducts();break;case"sales":showSale();break;case"purchase":showPurchase();break;case"payments":showPayment();break;case"reports":showReports();break;case"backup":showBackup();break;}}
  void section(String s){TextView t=text(s,18,DEEP);t.setTypeface(null,1);body.addView(t);}
  void note(String s){body.addView(text(s,14,INK));}
  void showHome(){base("दुकान प्रबंधन ऐप");section("नमस्ते! 🙏");note("ग्राहक, पशु आहार, बिक्री, खरीद और उधारी का हिसाब एक ही जगह रखें।");double due=db.scalar("SELECT COALESCE(SUM(total),0)-COALESCE(SUM(paid),0) FROM (SELECT c.id, (SELECT COALESCE(SUM(amount),0) FROM tx WHERE customer_id=c.id AND kind='SALE') total, (SELECT COALESCE(SUM(amount),0) FROM tx WHERE customer_id=c.id AND kind='PAY') paid FROM customers c)");double stock=db.scalar("SELECT COALESCE(SUM(qty*price),0) FROM products");card("कुल बकाया","₹ "+money(due));card("स्टॉक का अनुमानित मूल्य","₹ "+money(stock));body.addView(button("＋ नई बिक्री / उधारी",()->go("sales")));body.addView(button("＋ ग्राहक जोड़ें",()->go("customers")));body.addView(button("＋ सामान / रेट जोड़ें",()->go("products")));body.addView(button("＋ खरीद दर्ज करें",()->go("purchase")));body.addView(button("＋ ग्राहक से भुगतान",()->go("payments")));body.addView(button("📊 ग्राहक हिसाब / रिपोर्ट",()->go("reports")));body.addView(button("💾 डेटा बैकअप / एक्सपोर्ट",()->go("backup")));}
  void card(String a,String b){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(12,7,12,7);c.setBackground(bg(Color.WHITE,14));TextView t=text(a,14,INK),v=text(b,23,DEEP);v.setTypeface(null,1);c.addView(t);c.addView(v);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,5,0,8);body.addView(c,p);}
  void showCustomers(){base("ग्राहक सूची और बहीखाता");section("नया ग्राहक जोड़ें");EditText n=edit("ग्राहक का नाम *",false),ph=edit("मोबाइल नंबर",true),addr=edit("गाँव / पता",false);body.addView(n);body.addView(ph);body.addView(addr);body.addView(button("ग्राहक सेव करें",()->{if(n.getText().toString().trim().isEmpty()){n.setError("नाम जरूरी है");return;}ContentValues v=new ContentValues();v.put("name",n.getText().toString().trim());v.put("phone",ph.getText().toString());v.put("address",addr.getText().toString());db.getWritableDatabase().insert("customers",null,v);showCustomers();}));section("ग्राहक (क्रम संख्या सहित)");Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,phone,address FROM customers ORDER BY name COLLATE NOCASE",null);int i=1;while(c.moveToNext()){long id=c.getLong(0);String nm=c.getString(1),phone=c.getString(2),ad=c.getString(3);double due=db.customerDue(id);LinearLayout row=new LinearLayout(this);row.setOrientation(1);row.setPadding(8,8,8,8);row.setBackground(bg(Color.WHITE,12));row.addView(text(i+++". "+nm,17,INK));row.addView(text((phone==null?"":phone)+"   |   बकाया: ₹"+money(due),14,due>0?DEEP:Color.rgb(46,125,50)));row.addView(button("पूरा हिसाब / WhatsApp शेयर",()->shareCustomer(id)));body.addView(row);LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)row.getLayoutParams();lp.setMargins(0,4,0,6);row.setLayoutParams(lp);}c.close();}
  void showProducts(){base("सामान और स्टॉक");section("सामान जोड़ें / रेट बदलें");EditText n=edit("सामान का नाम",false),pr=edit("प्रति बोरी / इकाई बिक्री रेट ₹",true),qty=edit("मौजूदा स्टॉक (बोरी/इकाई)",true);body.addView(n);body.addView(pr);body.addView(qty);body.addView(button("सामान सेव करें",()->{if(n.getText().toString().trim().isEmpty()||num(pr)<=0){toast("नाम और सही रेट भरें");return;}ContentValues v=new ContentValues();v.put("name",n.getText().toString().trim());v.put("price",num(pr));v.put("qty",Math.max(0,num(qty)));db.getWritableDatabase().insert("products",null,v);showProducts();}));section("स्टॉक सूची");Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name,price,qty FROM products ORDER BY name",null);while(c.moveToNext()){long id=c.getLong(0);String nm=c.getString(1);double price=c.getDouble(2),q=c.getDouble(3);LinearLayout r=new LinearLayout(this);r.setOrientation(1);r.setPadding(8,6,8,6);r.setBackground(bg(Color.WHITE,10));r.addView(text(nm,16,INK));r.addView(text("रेट ₹"+money(price)+"  |  स्टॉक "+money(q),14,DEEP));r.addView(button("रेट / स्टॉक अपडेट",()->editProduct(id,nm,price,q)));body.addView(r);}c.close();}
  void editProduct(long id,String nm,double price,double qty){LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText p=edit("नया रेट",true),q=edit("नया स्टॉक",true);p.setText(""+price);q.setText(""+qty);l.addView(p);l.addView(q);new AlertDialog.Builder(this).setTitle(nm).setView(l).setPositiveButton("सेव",(d,w)->{ContentValues v=new ContentValues();v.put("price",num(p));v.put("qty",num(q));db.getWritableDatabase().update("products",v,"id=?",new String[]{""+id});showProducts();}).setNegativeButton("रद्द",null).show();}
  void showSale(){base("बिक्री / ग्राहक की उधारी");Cursor cc=db.getReadableDatabase().rawQuery("SELECT id,name FROM customers ORDER BY name",null);ArrayList<String> cn=new ArrayList<>();customerIds.clear();while(cc.moveToNext()){customerIds.add(cc.getLong(0));cn.add(cc.getString(1));}cc.close();Cursor pc=db.getReadableDatabase().rawQuery("SELECT id,name,price,qty FROM products ORDER BY name",null);ArrayList<String> pn=new ArrayList<>();productIds.clear();ArrayList<Double> prices=new ArrayList<>(),stocks=new ArrayList<>();while(pc.moveToNext()){productIds.add(pc.getLong(0));pn.add(pc.getString(1)+" (स्टॉक "+money(pc.getDouble(3))+")");prices.add(pc.getDouble(2));stocks.add(pc.getDouble(3));}pc.close();if(cn.isEmpty()||pn.isEmpty()){note("पहले ग्राहक और सामान जोड़ें।");body.addView(button("ग्राहक जोड़ें",()->go("customers")));body.addView(button("सामान जोड़ें",()->go("products")));return;}section("नई बिक्री दर्ज करें");Spinner cs=spinner(cn),ps=spinner(pn);EditText q=edit("मात्रा / बोरी",true),rate=edit("रेट ₹ (ऑटो भरेगा)",true);body.addView(text("ग्राहक",14,INK));body.addView(cs);body.addView(text("सामान",14,INK));body.addView(ps);body.addView(q);body.addView(rate);ps.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int pos,long id){rate.setText(""+prices.get(pos));}});body.addView(button("बिक्री सेव करें और स्टॉक घटाएँ",()->{int ci=cs.getSelectedItemPosition(),pi=ps.getSelectedItemPosition();double quantity=num(q),r=num(rate);if(quantity<=0||r<=0){toast("मात्रा और रेट सही भरें");return;}if(quantity>stocks.get(pi)){toast("स्टॉक कम है: "+money(stocks.get(pi)));return;}long customer=customerIds.get(ci),product=productIds.get(pi);db.sale(customer,product,quantity,r);toast("बिक्री सेव हुई: ₹"+money(quantity*r));go("home");}));}
  Spinner spinner(ArrayList<String> values){Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);s.setAdapter(a);return s;}
  void showPurchase(){base("खरीद / स्टॉक बढ़ाएँ");Cursor pc=db.getReadableDatabase().rawQuery("SELECT id,name,qty FROM products ORDER BY name",null);ArrayList<Long> ids=new ArrayList<>();ArrayList<String> names=new ArrayList<>();while(pc.moveToNext()){ids.add(pc.getLong(0));names.add(pc.getString(1)+" (स्टॉक "+money(pc.getDouble(2))+")");}pc.close();if(names.isEmpty()){note("पहले सामान जोड़ें।");return;}Spinner sp=spinner(names);EditText q=edit("खरीदी मात्रा",true),cost=edit("कुल खरीद लागत ₹ (वैकल्पिक)",true),supplier=edit("सप्लायर का नाम (वैकल्पिक)",false);body.addView(sp);body.addView(q);body.addView(cost);body.addView(supplier);body.addView(button("खरीद सेव करें / स्टॉक बढ़ाएँ",()->{double quantity=num(q);if(quantity<=0){toast("मात्रा भरें");return;}db.purchase(ids.get(sp.getSelectedItemPosition()),quantity,num(cost),supplier.getText().toString());toast("खरीद दर्ज हुई");go("home");}));section("हाल की खरीद");Cursor c=db.getReadableDatabase().rawQuery("SELECT detail,amount,created FROM tx WHERE kind='PURCHASE' ORDER BY id DESC LIMIT 30",null);while(c.moveToNext())note(c.getString(2)+" — "+c.getString(0)+" — ₹"+money(c.getDouble(1)));c.close();}
  void showPayment(){base("ग्राहक से जमा भुगतान");Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM customers ORDER BY name",null);ArrayList<Long> ids=new ArrayList<>();ArrayList<String> names=new ArrayList<>();while(c.moveToNext()){ids.add(c.getLong(0));names.add(c.getString(1));}c.close();if(names.isEmpty()){note("पहले ग्राहक जोड़ें।");return;}Spinner sp=spinner(names);EditText amt=edit("जमा राशि ₹",true),memo=edit("टिप्पणी / माध्यम",false);body.addView(sp);body.addView(amt);body.addView(memo);body.addView(button("भुगतान सेव करें",()->{double a=num(amt);if(a<=0){toast("सही राशि भरें");return;}db.payment(ids.get(sp.getSelectedItemPosition()),a,memo.getText().toString());toast("भुगतान सेव हुआ");go("home");}));}
  void showReports(){base("बहीखाता / ग्राहक रिपोर्ट");section("ग्राहक चुनें");Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM customers ORDER BY name",null);int i=1;while(c.moveToNext()){long id=c.getLong(0);String n=c.getString(1);body.addView(button((i++)+". "+n+" — बकाया ₹"+money(db.customerDue(id)),()->shareCustomer(id)));}c.close();body.addView(button("सभी लेन-देन देखें",()->showTransactions()));}
  void showTransactions(){base("सभी लेन-देन");Cursor c=db.getReadableDatabase().rawQuery("SELECT created,detail,amount,kind FROM tx ORDER BY id DESC LIMIT 200",null);while(c.moveToNext())note(c.getString(0)+" | "+c.getString(1)+" | ₹"+money(c.getDouble(2))+" | "+c.getString(3));c.close();}
  void shareCustomer(long id){Cursor c=db.getReadableDatabase().rawQuery("SELECT name,phone FROM customers WHERE id=?",new String[]{""+id});if(!c.moveToFirst()){c.close();return;}String name=c.getString(0),phone=c.getString(1);c.close();StringBuilder s=new StringBuilder("🙏 श्री कष्टभंजन देव 🙏\nश्री कष्टभंजन देव पशु आहार करजी\nग्राहक: "+name+"\n");if(phone!=null)s.append("मोबाइल: ").append(phone).append("\n");s.append("तारीख: ").append(new SimpleDateFormat("dd-MM-yyyy",Locale.getDefault()).format(new Date())).append("\n\nदिनांक | विवरण | राशि\n");Cursor tx=db.getReadableDatabase().rawQuery("SELECT created,detail,amount,kind FROM tx WHERE customer_id=? ORDER BY id",new String[]{""+id});double sales=0,pays=0;while(tx.moveToNext()){String kind=tx.getString(3);double a=tx.getDouble(2);s.append(tx.getString(0)).append(" | ").append(tx.getString(1)).append(" | ₹").append(money(a)).append("\n");if("SALE".equals(kind))sales+=a;else if("PAY".equals(kind))pays+=a;}tx.close();s.append("\nकुल बिक्री: ₹").append(money(sales)).append("\nकुल जमा: ₹").append(money(pays)).append("\n");double due=sales-pays;s.append("बकाया राशि: ₹").append(money(due)).append("\n\nधन्यवाद 🙏");Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,s.toString());try{startActivity(Intent.createChooser(send,"WhatsApp / शेयर करें"));}catch(Exception e){toast(s.toString());}}
  void showBackup(){base("डेटा सुरक्षा");section("बैकअप / एक्सपोर्ट");note("इस संस्करण में डेटा इसी फोन में SQLite डेटाबेस में रखा जाता है। फोन बदलने या ऐप हटाने से पहले बैकअप जरूरी है।");body.addView(button("डेटा CSV रिपोर्ट शेयर करें",()->exportCsv()));note("ध्यान दें: इस शुरुआती नेटिव प्रोजेक्ट में CSV एक्सपोर्ट उपलब्ध है। JSON बैकअप इम्पोर्ट/रीस्टोर और फोटो/PDF स्टेटमेंट अगले विकास चरण में जोड़े जाने चाहिए; अभी इनके पूरे होने का दावा नहीं किया जा रहा है।");}
  void exportCsv(){try{File f=new File(getCacheDir(),"kashtbhanjan_ledger.csv");PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(f),"UTF-8"));w.println("Date,Customer,Type,Details,Amount");Cursor c=db.getReadableDatabase().rawQuery("SELECT tx.created,COALESCE(customers.name,''),tx.kind,tx.detail,tx.amount FROM tx LEFT JOIN customers ON customers.id=tx.customer_id ORDER BY tx.id",null);while(c.moveToNext())w.println(csv(c.getString(0))+","+csv(c.getString(1))+","+csv(c.getString(2))+","+csv(c.getString(3))+","+c.getDouble(4));c.close();w.close();Uri uri=androidxUri(f);Intent in=new Intent(Intent.ACTION_SEND);in.setType("text/csv");in.putExtra(Intent.EXTRA_STREAM,uri);in.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(in,"CSV बैकअप शेयर करें"));}catch(Exception e){toast("एक्सपोर्ट नहीं हुआ: "+e.getMessage());}}
  Uri androidxUri(File f){return Uri.fromFile(f);}String csv(String s){if(s==null)return "\"\"";return "\""+s.replace("\"","\"\"").replace(","," ")+"\"";}
  double num(EditText e){try{return Double.parseDouble(e.getText().toString().trim());}catch(Exception x){return 0;}}String money(double d){return String.format(Locale.US,"%.2f",d);}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
  class DB extends SQLiteOpenHelper {DB(Context c){super(c,"kashtbhanjan.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE customers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT,address TEXT)");d.execSQL("CREATE TABLE products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,price REAL NOT NULL,qty REAL NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE tx(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER,product_id INTEGER,kind TEXT,detail TEXT,amount REAL,qty REAL,created TEXT)");}public void onUpgrade(SQLiteDatabase d,int a,int b){}double scalar(String sql){Cursor c=getReadableDatabase().rawQuery(sql,null);double v=0;if(c.moveToFirst())v=c.getDouble(0);c.close();return v;}double customerDue(long id){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(CASE WHEN kind='SALE' THEN amount WHEN kind='PAY' THEN -amount ELSE 0 END),0) FROM tx WHERE customer_id=?",new String[]{""+id});double v=c.moveToFirst()?c.getDouble(0):0;c.close();return v;}void sale(long cid,long pid,double qty,double rate){SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try{Cursor c=d.rawQuery("SELECT name FROM products WHERE id=?",new String[]{""+pid});String n=c.moveToFirst()?c.getString(0):"सामान";c.close();ContentValues v=new ContentValues();v.put("qty",-qty);d.execSQL("UPDATE products SET qty=qty-? WHERE id=?",new Object[]{qty,pid});ContentValues t=new ContentValues();t.put("customer_id",cid);t.put("product_id",pid);t.put("kind","SALE");t.put("detail",n+" × "+money(qty)+" @ ₹"+money(rate));t.put("amount",qty*rate);t.put("qty",qty);t.put("created",new SimpleDateFormat("dd-MM-yyyy HH:mm",Locale.getDefault()).format(new Date()));d.insert("tx",null,t);d.setTransactionSuccessful();}finally{d.endTransaction();}}void purchase(long pid,double qty,double cost,String supplier){SQLiteDatabase d=getWritableDatabase();d.execSQL("UPDATE products SET qty=qty+? WHERE id=?",new Object[]{qty,pid});Cursor c=d.rawQuery("SELECT name FROM products WHERE id=?",new String[]{""+pid});String n=c.moveToFirst()?c.getString(0):"सामान";c.close();ContentValues t=new ContentValues();t.put("product_id",pid);t.put("kind","PURCHASE");t.put("detail",n+" खरीद × "+money(qty)+(supplier.isEmpty()?"":" | "+supplier));t.put("amount",cost);t.put("qty",qty);t.put("created",new SimpleDateFormat("dd-MM-yyyy HH:mm",Locale.getDefault()).format(new Date()));d.insert("tx",null,t);}void payment(long cid,double amount,String memo){ContentValues t=new ContentValues();t.put("customer_id",cid);t.put("kind","PAY");t.put("detail","जमा भुगतान"+(memo.isEmpty()?"":" — "+memo));t.put("amount",amount);t.put("created",new SimpleDateFormat("dd-MM-yyyy HH:mm",Locale.getDefault()).format(new Date()));getWritableDatabase().insert("tx",null,t);}}
}
